CREATE TABLE IF NOT EXISTS exams(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),academic_year TEXT NOT NULL,semester TEXT NOT NULL,exam_name TEXT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS exam_schedules(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),exam_id UUID NOT NULL REFERENCES exams(id) ON DELETE CASCADE,subject_id UUID REFERENCES subjects(id),exam_date DATE NOT NULL,start_time TIME,end_time TIME,room TEXT,seat_no TEXT);
CREATE TABLE IF NOT EXISTS hall_tickets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),student_id UUID NOT NULL REFERENCES app_users(id),exam_id UUID NOT NULL REFERENCES exams(id) ON DELETE CASCADE,hall_ticket_number TEXT UNIQUE NOT NULL,status TEXT NOT NULL DEFAULT 'PUBLISHED' CHECK(status IN ('DRAFT','PUBLISHED','REVOKED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(student_id,exam_id));
CREATE INDEX IF NOT EXISTS idx_exam_schedule_date ON exam_schedules(exam_date);CREATE INDEX IF NOT EXISTS idx_hall_ticket_student ON hall_tickets(student_id);
